// Runtime pack, mechanics: how a tick runs for a player, intents, pathfinding, visibility,
// the event log, find and look. Plus additions to mechanic:cpu, mechanic:memory, mechanic:tick-order.
const { L, eng, driver, doc, article, common } = require('../../_h');

const G = 'src/game/';
const P = 'src/processor/intents/';
